def keep_cosmos(apps, schema_editor):
    """A Cosmos virou módulo: quem já usava continua usando. Quem foi desligado no admin fica sem o módulo."""
    Account = apps.get_model("starrp", "Account")
    for account in Account.objects.filter(cosmos_enabled=True):
        modules = account.extra_modules or []
        if "cosmos" not in modules:
            Account.objects.filter(pk=account.pk).update(extra_modules=[*modules, "cosmos"])


